/**
 * AI 怪物美術的產圖清單（`25-monster-system.md` § 25.2.2）。
 *
 * body 'beast'：四足獸，大圓身體＋短腿；'creature'：其餘造型照 subject 描述；'custom'：subject 自帶視圖描述；
 * base：以底圖（`assets-src/monster-bases/<key>.png`，`demo/monster-base.html` 匯出）做 img2img，強度 denoise，底圖側面朝右；
 *   shape 省略＝角色剪影（膚色、衣色、選填髮型與髮色，'humanoid' 用），'wyvern'＝Wyvern 剪影、'twin-dragon'＝雙頭龍剪影（身體、腹、翼、角的顏色）。
 * 'humanoid'：RimWorld 殖民者比例，搭配角色剪影底圖。
 * legs 'trim' 由後處理裁腿；'keep' 不裁（無腿、腿是造型本體或飛行）。
 * sideFacesLeft：該 seed 原圖的側面朝左（後處理鏡像成朝右）。
 * enclosedTolerance：被圍住的背景色不均、殘留洋紅時才指定（見 `keyOutBackground`）。
 * legTrim：頭部比身體寬、衣襬逐漸收窄（兜帽長袍）時指定，裁腿改以底部 region 內最寬列 × coverage 為準（`HOODED_LEG_TRIM`；袖子伸出長袍時用 `ROBE_LEG_TRIM`）。
 * baseRaw：以該 key 的 AI 原圖（`assets-src/ai-raw/monsters/<baseRaw>.png`）做 img2img，強度 denoise；側面朝向、裁腿等沿用原怪物。
 * 同一 seed 必得同一張圖；改 prompt 或 seed 即換圖。
 */

const STYLE = 'identical design and colors in every view, RimWorld art style, simple hand-painted 2D game sprite, minimal detail, smooth clean edges, thick dark outline, flat cel shading, muted natural colors';
const BACKDROP = 'isolated on a pure flat fully saturated magenta (#FF00FF) background, no ground, no shadow, no text, not pixel art';
const COMMON = `${STYLE}, evenly spaced, ${BACKDROP}`;

/** 兜帽長袍的裁腿判定 */
const HOODED_LEG_TRIM = { region: 0.3, coverage: 0.75 };
/** 兜帽長袍且袖子伸出袍外的裁腿判定（最寬列只取到袍襬） */
const ROBE_LEG_TRIM = { region: 0.15, coverage: 0.75 };

/** 底圖 img2img 強度預設值（job 可個別指定 denoise） */
const BASE_DENOISE = 0.7;

const BODY = {
  beast: `three views of the same animal standing in a row: front view, side view, back view, chunky plush toy proportions, a large rounded body takes up almost all of the height, extremely short stubby legs hidden beneath the body, ${COMMON}`,
  humanoid: `three views of the same character in a row: front view, side view facing right, back view, RimWorld colonist pawn: a big round head on a short sack-shaped torso of the same width, no legs, no feet, the torso ends in a rounded bottom, ${STYLE}, ${BACKDROP}`,
  creature: `three views of the same creature in a row: front view, side view, back view, chunky simple rounded silhouette, ${COMMON}`,
  custom: COMMON,
};

const job = (id, key, body, subject, { seed = 1, legs = ['creature', 'custom'].includes(body) ? 'keep' : 'trim', sideFacesLeft = body !== 'humanoid', enclosedTolerance, legTrim, base, denoise = BASE_DENOISE } = {}) =>
  ({ id, key, legs, sideFacesLeft, enclosedTolerance, legTrim, seed, prompt: `${subject}, ${BODY[body]}`, ...(base && { base, denoise }) });

/** 產圖批次（demo 依此分頁） */
const group = (name, jobs) => jobs.map(item => ({ ...item, group: name }));

